file.content:
.skills-panel {
  padding: 0;
}

.skills-panel__actions {
  display: flex;
  justify-content: flex-end;
  padding: 0 0 8px;
}

.skills-panel__create-btn {
  background: none;
  border: 1px solid var(--color-border-medium);
  cursor: pointer;
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  color: var(--color-text-muted);
  font-size: 18px;
  line-height: 1;
  transition: background 0.15s, color 0.15s;
}

.skills-panel__create-btn:hover {
  background: var(--color-bg-hover-strong);
  color: var(--color-text-primary);
}

.skills-panel__empty {
  font-size: 13px;
  color: var(--color-text-faint);
  padding: 0;
  margin: 0;
}

.skills-panel__list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.skills-panel__item {
  margin-bottom: 8px;
  padding: 8px;
  border-radius: 6px;
  border: 1px solid var(--color-border-light);
  cursor: pointer;
}

.skills-panel__item:hover {
  border-color: var(--color-border-medium);
}

.skills-panel__item-header {
  display: flex;
  align-items: center;
  gap: 6px;
}

.skills-panel__name {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text-primary);
  padding: 0;
  text-align: left;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skills-panel__loading {
  font-size: 12px;
  color: var(--color-text-muted);
}

.skills-panel__use-btn {
  background: var(--color-accent-primary);
  color: #fff;
  border: none;
  border-radius: 4px;
  font-size: 11px;
  padding: 2px 8px;
  cursor: pointer;
  white-space: nowrap;
}

.skills-panel__use-btn:hover {
  background: var(--color-accent-primary-hover);
}

.skills-panel__delete-btn {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 16px;
  color: var(--color-text-muted);
  padding: 0 2px;
  opacity: 1;
}

.skills-panel__delete-btn:hover {
  color: var(--color-error);
}

.skills-panel__desc {
  font-size: 12px;
  color: var(--color-text-muted);
  margin: 4px 0 0;
  line-height: 1.4;
}

.skills-panel__item--disabled {
  opacity: 0.5;
}

.skills-panel__toggle-btn {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--color-text-muted);
  padding: 0 2px;
  line-height: 1;
  display: flex;
  align-items: center;
  transition: color 0.15s;
}

.skills-panel__toggle-btn:hover {
  color: var(--color-text-primary);
}

.skills-panel__desc--truncated {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Detail modal */

.skill-detail-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

.skill-detail-modal {
  background: var(--color-bg-primary);
  border: 1px solid var(--color-border-medium);
  border-radius: 12px;
  padding: 24px;
  width: 560px;
  max-width: 90vw;
  max-height: 80vh;
  display: flex;
  flex-direction: column;
}

.skill-detail-modal__header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
}

.skill-detail-modal__name {
  font-size: 16px;
  font-weight: 600;
  color: var(--color-text-primary);
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skill-detail-modal__close {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 20px;
  color: var(--color-text-muted);
  padding: 0 4px;
  line-height: 1;
}

.skill-detail-modal__close:hover {
  color: var(--color-text-primary);
}

.skill-detail-modal__desc {
  font-size: 13px;
  color: var(--color-text-muted);
  margin: 0 0 12px;
  line-height: 1.4;
}

.skill-detail-modal__tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 8px;
}

.skill-detail-modal__tab {
  background: none;
  border: 1px solid var(--color-border-light);
  border-radius: 4px;
  padding: 4px 12px;
  font-size: 12px;
  color: var(--color-text-muted);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}

.skill-detail-modal__tab:hover {
  background: var(--color-bg-hover-strong);
  color: var(--color-text-primary);
}

.skill-detail-modal__tab--active {
  background: var(--color-accent-primary);
  color: #fff;
  border-color: var(--color-accent-primary);
}

.skill-detail-modal__tab--active:hover {
  background: var(--color-accent-primary-hover);
}

.skill-detail-modal__content {
  font-size: 12px;
  font-family: monospace;
  color: var(--color-text-secondary);
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border-light);
  border-radius: 6px;
  padding: 12px;
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
  line-height: 1.5;
  overflow-y: auto;
  flex: 1;
  min-height: 0;
}

.skill-detail-modal__content--preview {
  font-family: inherit;
  white-space: normal;
}

.skill-detail-modal__content--preview h1,
.skill-detail-modal__content--preview h2,
.skill-detail-modal__content--preview h3 {
  margin: 12px 0 6px;
  color: var(--color-text-primary);
}

.skill-detail-modal__content--preview h1 { font-size: 18px; }
.skill-detail-modal__content--preview h2 { font-size: 15px; }
.skill-detail-modal__content--preview h3 { font-size: 13px; }

.skill-detail-modal__content--preview p {
  margin: 6px 0;
}

.skill-detail-modal__content--preview ul,
.skill-detail-modal__content--preview ol {
  margin: 6px 0;
  padding-left: 20px;
}

.skill-detail-modal__content--preview code {
  background: var(--color-bg-primary);
  border: 1px solid var(--color-border-light);
  border-radius: 3px;
  padding: 1px 4px;
  font-size: 11px;
  font-family: monospace;
}

.skill-detail-modal__content--preview pre {
  background: var(--color-bg-primary);
  border: 1px solid var(--color-border-light);
  border-radius: 6px;
  padding: 8px;
  margin: 6px 0;
  overflow-x: auto;
}

.skill-detail-modal__content--preview pre code {
  background: none;
  border: none;
  padding: 0;
}

.skill-detail-modal__content--preview table {
  border-collapse: collapse;
  width: 100%;
  margin: 6px 0;
  font-size: 12px;
}

.skill-detail-modal__content--preview th,
.skill-detail-modal__content--preview td {
  border: 1px solid var(--color-border-light);
  padding: 4px 8px;
  text-align: left;
}

.skill-detail-modal__content--preview th {
  background: var(--color-bg-primary);
  font-weight: 600;
}
